#!/usr/bin/env python3
"""Writes res/content/learn.json: lessons with quizzes, the glossary, and the "?" explanations.
Edit the text here and run:  python3 tools/learn_content.py"""
import json, os

def L(id, level, title, minutes, summary, sections, takeaways, quiz, terms):
    return dict(id=id, level=level, title=title, minutes=minutes, summary=summary,
                sections=[dict(h=h, p=p) for h, p in sections], takeaways=takeaways,
                quiz=[dict(q=q, options=o, answer=a, why=w) for q, o, a, w in quiz], terms=terms)

