GLOSSARY = [
 ("200-day moving average", "The average closing price over the last 200 trading days. A widely watched long-term trend line."),
 ("Adjusted price", "A historical price revised so splits don't look like crashes and dividends are counted as if reinvested. Signal Desk's charts and returns use adjusted prices."),
 ("Annualized return (CAGR)", "The steady yearly growth rate that would turn the starting value into the ending value over the same period. Short for compound annual growth rate."),
 ("Asset allocation", "How your money is split among kinds of investments, such as stocks, bonds and cash."),
 ("Backtest", "A replay of trading rules on past prices to see how they would have behaved. It does not predict future results."),
 ("Beta", "How much an investment tends to move with the overall market. 1 moves in step with the S&P 500; above 1 moves more; below 1 moves less."),
 ("Bid–ask spread", "The gap between the highest price a buyer offers and the lowest price a seller asks. A hidden cost of every trade."),
 ("Blockchain", "A shared, public record of transactions that cryptocurrencies use instead of a central bank or company."),
 ("Bollinger Bands", "Lines drawn two standard deviations above and below a 20-day average. They widen in volatile periods and narrow in calm ones."),
 ("Bond", "A loan to a government or company that pays interest and returns the amount borrowed at a set date."),
 ("Buy and hold", "Buying an investment and keeping it through ups and downs instead of trading in and out."),
 ("Candlestick", "A chart mark for one period showing open, high, low and close. The body spans open to close; the wicks reach the high and low."),
 ("Capital gain", "Profit from selling an investment for more than you paid. Often taxed, with rates depending on how long you held it."),
 ("Commission", "A fee a broker charges per trade. Many brokers now charge none for stocks and ETFs."),
 ("Compounding", "Earning returns on earlier returns, so growth accelerates over time."),
 ("Correlation", "How closely two investments move together, from −1 (opposite) through 0 (unrelated) to +1 (in lockstep)."),
 ("Cryptocurrency", "A digital token recorded on a blockchain, such as Bitcoin or Ether. Trades every day and is typically very volatile."),
 ("Death cross", "When the 50-day moving average crosses below the 200-day. Seen as a sign the trend has turned down."),
 ("Diversification", "Spreading money across many investments so no single one can do too much damage."),
 ("Dividend", "Cash a company pays shareholders out of its profits, often every quarter."),
 ("Drawdown", "The fall from a peak to a later low, as a percentage."),
 ("ETF", "Exchange-traded fund: a fund whose shares trade on a stock exchange throughout the day, usually tracking an index."),
 ("Expense ratio", "A fund's yearly fee as a percentage of the money invested in it."),
 ("Exponential moving average (EMA)", "A moving average that gives more weight to recent prices, so it reacts faster than a simple average of the same length."),
 ("Fund", "A pool of money from many investors used to buy a basket of investments."),
 ("Golden cross", "When the 50-day moving average crosses above the 200-day. Seen as a sign the trend has turned up."),
 ("Index", "A published list of investments that measures a market, such as the S&P 500 or the Nasdaq Composite."),
 ("Index fund", "A fund that copies an index instead of picking investments. Usually low-cost."),
 ("Line chart", "A chart that connects closing prices. Best for seeing the trend over long ranges."),
 ("MACD", "Moving Average Convergence Divergence: the 12-day EMA minus the 26-day EMA. Compared with its own 9-day average (the signal line) to judge momentum."),
 ("Market capitalization", "Share price times the number of shares: what the market values the whole company at."),
 ("Maximum drawdown", "The worst peak-to-low fall over a period."),
 ("Momentum", "The tendency of recent winners to keep rising, and losers to keep falling, for a while."),
 ("Moving average (SMA)", "Simple moving average: the average closing price over the last N trading days, recalculated each day."),
 ("Mutual fund", "A fund bought from and sold back to the fund company once a day at its net asset value."),
 ("Net asset value", "The value of everything a fund holds, minus what it owes, divided by its shares. Mutual funds trade at this price once a day."),
 ("OHLC bar", "A chart mark showing open (left tick), high and low (vertical line) and close (right tick) for one period."),
 ("Overbought", "A price that has risen quickly, often taken as RSI above 70. It can stay overbought in a strong trend."),
 ("Oversold", "A price that has fallen quickly, often taken as RSI below 30."),
 ("Overfitting", "Tuning rules so closely to past data that they capture noise and fail on new data."),
 ("Paper trading", "Practicing trades with pretend money at real prices. Signal Desk's Practice portfolio does this."),
 ("Return", "The gain or loss on an investment as a percentage of what you started with."),
 ("Risk tolerance", "How much loss and uncertainty you can live with without abandoning your plan."),
 ("RSI (Relative Strength Index)", "A 0–100 momentum gauge comparing recent up moves with down moves. Above 70 is called overbought, below 30 oversold."),
 ("Screening", "Filtering and ranking many investments by rules to find candidates for closer research."),
 ("Sector", "A group of companies in the same broad industry, such as technology or energy."),
 ("Share", "One unit of ownership in a company or fund."),
 ("Signal line", "The 9-day average of MACD. MACD crossing above it suggests improving momentum."),
 ("Slippage", "The difference between the price you expected and the price you actually got."),
 ("Standard deviation", "A measure of how spread out values are from their average. Applied to returns, it measures volatility."),
 ("Stock", "Ownership in a company, divided into shares."),
 ("Stock split", "A company dividing each share into several (or combining several into one). It changes the share count and price, not the company's value."),
 ("Total return", "Price change plus dividends or other payouts, over a period."),
 ("Trailing stop", "A sell rule that triggers when price falls a set percentage below its highest point since you bought."),
 ("Trend", "The general direction of prices over a period: up, down or sideways."),
 ("Volatility", "How much prices swing, usually given as the yearly standard deviation of returns."),
 ("Volume", "The number of shares traded in a period. Heavy volume suggests more conviction behind a move."),
]

# Contextual help for the "?" buttons. Keys are used in the code.
EXPLAIN = {
 "price": ("Price", "The latest closing price, adjusted for splits and dividends. During market hours it's the latest trade; mutual funds update once a day after the close.", "Adjusted price"),
 "day": ("Day change", "How much the price moved from the previous close, as a percentage.", "Return"),
 "returns": ("Returns", "Price change over each period, including dividends. 1M, 3M and 6M are total changes; YTD is since the last close of the previous year; 3Y and 5Y are annualized, meaning the steady yearly rate that would produce the same total.", "Annualized return (CAGR)"),
 "range52": ("52-week range", "The lowest and highest prices over the past year. The marker shows where today's price sits in that range. Near the top often goes with an uptrend; near the bottom, a downtrend.", "Trend"),
 "vol": ("Volatility (1 year)", "How much the price typically swings in a year, from the standard deviation of daily returns. Around 15–20% is typical for a broad stock fund; 50% or more is common for crypto.", "Volatility"),
 "dd": ("Max drawdown", "The worst fall from a high to a later low. 1 year looks at the past year; All time looks at the full saved history.", "Maximum drawdown"),
 "beta": ("Beta vs S&P 500", "How much this tends to move when the S&P 500 moves, measured on daily returns over the past year. 1.0 moves in step; 1.5 about half again as much; 0.5 about half as much. Near 0 means it moves mostly on its own.", "Beta"),
 "avgvol": ("Average volume", "Average number of shares (or coins) traded per day over the last three months. Higher volume usually means easier, cheaper trading. Mutual funds don't trade on an exchange, so they have none.", "Volume"),
 "score": ("Signal Desk score", "A 0–100 ranking from price history only: Trend 30%, Momentum 30%, Risk 25%, Timing 15%. Strong is 70 and up, Positive 55–69, Neutral 40–54, Weak 25–39, Weakest below 25. It's a screen for research, not advice, and it knows nothing about earnings, valuation or news.", "Screening"),
 "trend": ("Trend score", "Points for price above its 200-day average (35), above its 50-day (20), the 50-day above the 200-day (25), and the 200-day average rising over the last month (20).", "200-day moving average"),
 "momentum": ("Momentum score", "Mostly the 12-month return (60%), scaled so −30% scores 0 and +40% scores 100, plus the 3-month return (40%), scaled from −15% to +15%.", "Momentum"),
 "risk": ("Risk score", "Calmer scores higher. Mostly yearly volatility (60%), scaled so 80% scores 0 and 12% scores 100, plus the worst drop in the past year (40%), scaled from −60% to −8%.", "Volatility"),
 "timing": ("Timing score", "From the buy/sell model's current call: Buy 100, Hold 75, Wait 30–45 (higher in an uptrend), Sell 5. Overbought RSI subtracts 25.", "Overbought"),
 "call": ("Today's call", "What the buy/sell rules say on the latest close. Buy and Sell mean a signal fired today. Hold means the rules would be in the position; Wait means they'd be in cash.", "Backtest"),
 "backtest": ("Backtest results", "The buy/sell rules replayed over the last five years, trading at the next day's close and charging the cost per trade, compared with buying and holding for the same period.", "Backtest"),
 "chart-type": ("Chart types", "Line connects closing prices; it's clearest for long ranges. Candles and OHLC bars show each day's open, high, low and close. Green (or hollow) means it closed up on the day; red means down.", "Candlestick"),
 "sma": ("Strategy averages", "The fast and slow simple moving averages the buy/sell rules use (20 and 50 days by default). The fast crossing above the slow is the trend part of a buy signal.", "Moving average (SMA)"),
 "ema21": ("EMA 21", "A 21-day exponential moving average, weighted toward recent days. A common short-term trend line.", "Exponential moving average (EMA)"),
 "sma200": ("SMA 200", "The 200-day simple moving average. Price above a rising 200-day is the classic long-term uptrend sign.", "200-day moving average"),
 "bb": ("Bollinger Bands", "Lines two standard deviations above and below the 20-day average. Wide bands mean volatile prices; a touch of a band means a large move for recent conditions.", "Bollinger Bands"),
 "signals": ("Buy and sell markers", "Triangles where the rules fired in the backtest window: up for buys, down for sells. Hover a day to read why.", "Backtest"),
 "volume": ("Volume panel", "Shares traded each day, colored by whether the day closed up or down.", "Volume"),
 "rsi": ("RSI panel", "The 14-day Relative Strength Index, from 0 to 100. The shaded lines mark overbought and oversold levels from your strategy settings.", "RSI (Relative Strength Index)"),
 "macd": ("MACD panel", "MACD (12-day EMA minus 26-day EMA), its 9-day signal line, and the histogram of the gap between them.", "MACD"),
 "equity": ("Strategy vs buy & hold", "Growth of $10,000 following the rules compared with simply holding, over the backtest window.", "Buy and hold"),
 "practice": ("Practice portfolio", "Pretend money at real, latest saved prices. Trades fill instantly at the last close with no fees, and fractional shares are allowed. Nothing here touches a real account.", "Paper trading"),
 "vs-sp": ("Compared with the S&P 500", "What the same money would be worth if every deposit had gone into an S&P 500 index on the day your practice portfolio started.", "Index"),
 "asset-type": ("Asset type", "Stock, ETF, mutual fund, crypto or index, as reported by the price service. It affects trading hours, how returns are annualized, and which lessons apply.", "Fund"),
}

out = dict(lessons=LESSONS,
           glossary=[dict(term=t, def_=d) for t, d in sorted(GLOSSARY, key=lambda x: x[0].lower())],
           explain={k: dict(title=a, body=b, term=c) for k, (a, b, c) in EXPLAIN.items()})
# check every referenced glossary term exists
terms = {g["term"] for g in out["glossary"]}
missing = [t for l in LESSONS for t in l["terms"] if t not in terms] + [v["term"] for v in out["explain"].values() if v["term"] not in terms]
assert not missing, missing
for l in LESSONS:
    assert len(l["quiz"]) == 3 and all(0 <= q["answer"] < len(q["options"]) for q in l["quiz"]), l["id"]
for g in out["glossary"]: g["def"] = g.pop("def_")
p = os.path.join(os.path.dirname(__file__), "..", "res", "content", "learn.json")
with open(p, "w", encoding="utf-8") as f: json.dump(out, f, ensure_ascii=False, indent=1)
print(f"{len(LESSONS)} lessons, {len(GLOSSARY)} glossary terms, {len(EXPLAIN)} explanations -> {os.path.normpath(p)}")
